import json
import requests

from typing import Literal
from pydantic import BaseModel, ConfigDict

from app.agent.tools import list_tasks_tool, search_tasks_tool
from app.database import SessionLocal
from app.agent.tools import update_task_tool

OLLAMA_URL = "http://localhost:11434/api/chat"
MODEL_NAME = "qwen2.5:3b"


# 1. Validate arguments generated by the LLM
class ListTasksArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")

    status_filter: Literal["pending", "in_progress", "completed"] | None = None

    priority: Literal["low", "medium", "high"] | None = None


class SearchTasksArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")

    title: str


class UpdateTaskArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")

    task_id: int
    task_data: dict


# 2. Describe available tools to the LLM
tools = [
    {
        "type": "function",
        "function": {
            "name": "list_tasks",
            "description": "Retrieve tasks from TaskFlow.",
            "parameters": {
                "type": "object",
                "properties": {
                    "status_filter": {
                        "type": "string",
                        "enum": ["pending", "in_progress", "completed"],
                    },
                    "priority": {"type": "string", "enum": ["low", "medium", "high"]},
                },
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "search_tasks",
            "description": "Search tasks by title and return matching tasks.",
            "parameters": {
                "type": "object",
                "properties": {
                    "title": {
                        "type": "string",
                        "description": "The task title or a keyword from its title.",
                    }
                },
                "required": ["title"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "update_task",
            "description": "Update specific fields of an existing task using its task ID.",
            "parameters": {
                "type": "object",
                "properties": {
                    "task_id": {
                        "type": "integer",
                        "description": "The ID of the task to update.",
                    },
                    "task_data": {
                        "type": "object",
                        "properties": {
                            "title": {"type": "string"},
                            "description": {"type": "string"},
                            "priority": {
                                "type": "string",
                                "enum": ["low", "medium", "high"],
                            },
                            "status": {
                                "type": "string",
                                "enum": ["pending", "in_progress", "completed"],
                            },
                            "due_date": {
                                "type": "string",
                                "description": "Due date in YYYY-MM-DD format.",
                            },
                        },
                    },
                },
                "required": ["task_id", "task_data"],
            },
        },
    },
]


messages = [
    {
        "role": "system",
        "content": """
    You are a task management assistant.

    IMPORTANT WORKFLOW:
    - If the user asks to modify a task using its title,
      first call search_tasks.
    - After receiving search results, extract the task ID.
    - If exactly one matching task is found, immediately
      call update_task with that ID and the requested changes.
    - Do not tell the user that you will perform an update.
      Actually call the update_task tool.
    - Wait for the update result before confirming success.
    - Never claim an update succeeded unless the tool confirms it.
    - If the user explicitly provides a task ID, use that ID directly.
    Do not call search_tasks first.

    - If the user identifies a task by its title instead of an ID,
    call search_tasks first.

    - If search_tasks returns exactly one matching task,
    use its ID for the requested operation.

    - If search_tasks returns no matching tasks,
    do not attempt an update.

    - If search_tasks returns multiple matching tasks,
    ask the user to clarify which task they mean.
    """,
    },
    {
        "role": "user",
        "content": "Change the priority of task ID 5 to medium.",
    },
]


# 4. Start the agent loop
MAX_ROUNDS = 5

for round_number in range(MAX_ROUNDS):

    # Ask Ollama what to do
    response = requests.post(
        OLLAMA_URL,
        json={
            "model": MODEL_NAME,
            "messages": messages,
            "tools": tools,
            "stream": False,
        },
        timeout=120,
    )

    response.raise_for_status()

    assistant_message = response.json()["message"]
    print("\nRaw assistant message:")
    print(assistant_message)
    messages.append(assistant_message)

    # Check whether Ollama requested any tools
    tool_calls = assistant_message.get("tool_calls", [])

    # No more tools: Ollama has finished
    if not tool_calls:
        print("\nFinal AI answer:")
        print(assistant_message["content"])
        break

    # Execute each requested tool
    for tool_call in tool_calls:

        tool_name = tool_call["function"]["name"]
        arguments = tool_call["function"]["arguments"]

        print(f"\nRequested tool: {tool_name}")
        print("Arguments:", arguments)

        if tool_name == "list_tasks":
            validated_args = ListTasksArgs.model_validate(arguments)
            tool_function = list_tasks_tool

        elif tool_name == "search_tasks":
            validated_args = SearchTasksArgs.model_validate(arguments)
            tool_function = search_tasks_tool

        elif tool_name == "update_task":
            validated_args = UpdateTaskArgs.model_validate(arguments)
            tool_function = update_task_tool

        else:
            raise ValueError(f"Unknown tool: {tool_name}")

        db = SessionLocal()

        try:
            task_data = tool_function(
                db=db,
                **validated_args.model_dump(exclude_none=True),
            )
        finally:
            db.close()

        # Return the result to Ollama
        messages.append(
            {
                "role": "tool",
                "tool_name": tool_name,
                "content": json.dumps(task_data),
            }
        )

else:
    print("\nMaximum tool-call rounds reached.")

db = SessionLocal()

try:
    results = search_tasks_tool(db=db, title="Learn FastAPI")

    print("\nDatabase verification:")
    print("Priority:", results[0]["priority"])

finally:
    db.close()
